 public static void main(String[] a)throws Exception{MainActivity app=new MainActivity();app.onCreate(null);app.onResume();MainActivity.Radar v=app.view;check(app.menuMusic.isPlaying());draw(v,"menu-v06");v.act("start");check(!app.menuMusic.isPlaying());for(int i=0;i<2000;i++)v.game.tick(.05);for(Game.Contact t:v.game.contacts)if(v.game.liveTrack(t)){v.selected=t;v.game.track(t);v.game.illuminate(t);break;}draw(v,"gameplay-v06");Game.EnemyMissile m=new Game.EnemyMissile();m.id=105;m.weapon=4;m.x=m.px=8;m.y=m.py=-4;m.alt=m.palt=2400;m.z=2.4;m.pspeed=2400;m.samples=4;m.seen=v.game.elapsed;m.priority=true;v.game.enemyMissiles.add(m);v.selected=m;draw(v,"incoming-v06");v.game.start();v.game.contacts.clear();Game.Contact t=new Game.Contact();t.id=8;t.x=t.px=4;t.y=t.py=-1;t.alt=t.palt=1500;t.heading=Math.PI/2;t.samples=6;t.priority=true;t.seen=v.game.elapsed;t.pspeed=680;t.flareBursts=0;v.game.contacts.add(t);v.choose(t);v.act("weapon");v.act("illuminate");for(int i=0;i<70;i++)v.game.ir.tick(.05);check(v.game.ir.locked);draw(v,"ir-lock-v06");v.act("launch");check(v.game.ir.ammo==5);v.act("next");check(!v.game.ir.active);draw(v,"ir-flight-v06");v.game.damageRadar();draw(v,"damage-v06");v.act("menu");check(app.menuMusic.isPlaying());app.onPause();check(!app.menuMusic.isPlaying());app.onResume();check(app.menuMusic.isPlaying());app.focusListener.onAudioFocusChange(-1);check(!app.menuMusic.isPlaying());app.focusListener.onAudioFocusChange(1);check(app.menuMusic.isPlaying());app.onDestroy();System.out.println("PASS: desktop render and menu music lifecycle logic (stubbed media)");}
